function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });
    const [moved, setMoved] = useState(false);

    const move = () => {
        const x = Math.random() * (window.innerWidth - 200);
        const y = Math.random() * (window.innerHeight - 100);

        setPos({ x, y });
        setMoved(true);
    };

    return (
        <div className="home-page">

            <h1 className="title">Will you be my Valentine? 💝</h1>

            {/* YES */}
            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>

            {/* NO */}
            <button
                className="brutalist-button button-1 no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={
                    moved
                        ? { left: pos.x, top: pos.y, position: "absolute" }
                        : { position: "relative" }
                }
            >
                NO 😜
            </button>

        </div>
    );
}

/* DINO GAME */

function DinoGamePage({ onFinish }) {

    const [dinoY, setDinoY] = useState(0);
    const [velocity, setVelocity] = useState(0);
    const [cactusX, setCactusX] = useState(600);
    const [gameOver, setGameOver] = useState(false);

    const gravity = -0.8;
    const jumpPower = 14;
    const speed = 4;

    useEffect(() => {

        let animationId;

        const loop = () => {

            if (!gameOver) {

                /* Dino physics */
                setVelocity(v => {
                    let newV = v + gravity;

                    setDinoY(y => {
                        let newY = y + newV;

                        if (newY <= 0) {
                            newY = 0;
                            newV = 0;
                        }

                        return newY;
                    });

                    return newV;
                });

                /* Cactus move */
                setCactusX(x => {
                    let newX = x - speed;

                    if (newX < -40) newX = 600;

                    return newX;
                });

                /* Collision */
                setCactusX(x => {

                    if (
                        x < 90 &&
                        x > 20 &&
                        dinoY < 40
                    ) {
                        setGameOver(true);
                    }

                    return x;
                });
            }

            animationId = requestAnimationFrame(loop);
        };

        animationId = requestAnimationFrame(loop);

        return () => cancelAnimationFrame(animationId);

    }, [gameOver, dinoY]);

    const jump = () => {

        if (dinoY === 0 && !gameOver) {
            setVelocity(jumpPower);
        }
    };

    const restart = () => {

        setDinoY(0);
        setVelocity(0);
        setCactusX(600);
        setGameOver(false);
    };

    return (
        <div
            className="game-page"
            tabIndex="0"
            onClick={jump}
            onKeyDown={(e) => e.code === "Space" && jump()}
        >

            <h2>🦖 Dino Love Run 💖</h2>

            <div className="game-box">

                {/* Dino */}
                <div
                    className="dino"
                    style={{
                        bottom: dinoY,
                        left: 40,
                        position: "absolute"
                    }}
                >
                    🦕
                </div>

                {/* Cactus */}
                <div
                    className="cactus"
                    style={{
                        left: cactusX,
                        position: "absolute"
                    }}
                >
                    🌵
                </div>

            </div>

            {gameOver && (

                <div className="game-over">

                    <h3>Game Over 😢</h3>

                    <button
                        className="submit-button"
                        onClick={restart}
                    >
                        Restart 🔄
                    </button>

                    <button
                        className="submit-button"
                        style={{ marginTop: 10 }}
                        onClick={onFinish}
                    >
                        Continue 💖
                    </button>

                </div>
            )}

            <p>Click / Space to Jump</p>

        </div>
    );
}


